-- Barken: inte läst
-- Körd: före F57
-- 003 Taggar på inlägg för flödets filter på luminusloom.net:
-- arbete, musik, mat, aktivitet, grupp, resa, hemma, bild.
-- Ordlistorna är desamma som TAGG_ORD i public/index.html (raknaTaggar).
-- Triggern sätter data.taggar på nya och ändrade inlägg som saknar taggar, så att alla kommande inlägg taggas.
-- AI-skapat (B-051). Generated by AI, Directed by MS.

create or replace function public.luminus_post_taggar(d jsonb) returns jsonb
language plpgsql immutable set search_path = public as $$
declare
  b constant text := '(^|[^a-zåäöéü])';
  t text := coalesce(d->>'rubrik','') || ' ' || coalesce(d->>'text','');
  au text := coalesce(d->>'author','');
  ut text[] := '{}';
begin
  if d->>'typ' = 'team' or t ~* (b||'(möte|standup|retro|kodgransk|koden|sprint|kunden|kunder|rapport|uppdrag|workshop|deadline|granskning|jobb|arbet|projekt|mejl|presentation|kanban|leverans|pull request|kontor|demo|planering|tavlan|budget|ansökan|manus|skrivbord|dator|skiss|ritar|appen|sajten|flödet|regel|testlist|testet|databas|arkitektur|behörighet|data|beroenden|påminnelse|färgpalett|dialog|svarsmall|programmet|coach|teamet|kortspel|design|användare|besökare|kundtjänst|anteckn|prioriter|struktur)') then ut := ut || 'arbete'::text; end if;
  if t ~* (b||'(musik|låten|låtar|ny låt|en låt|sång|sjung|gitarr|trumm|piano|fiol|flöjt|tabla|synt|ackord|melodi|repetition|spelning|konsert|inspelning|studio|husbandet|karavanen|leonid|ek & lin|ek och lin|bandet|kören|körsång|vinyl|lyssna|suno|album|sitar|basen|didgeridoo|instrument|strängar|gitarren)') then ut := ut || 'musik'::text; end if;
  if d->>'typ' = 'recept' or au = 'marisol-quispe' or t ~* (b||'(recept|lunch|middag|frukost|fika|bröd|baka|bakning|soppa|gryta|köket|matlag|maten|mat |kaffe|gröt|smak|sylt|skörd|potatis|surdeg|pannkak|bulle|bullar|ugn|grönsak|rotfrukt|äter |vi åt)') then ut := ut || 'mat'::text; end if;
  if t ~* (b||'(promenad|morgonpromenad|kvällspromenad|turnering|mario kart|stjärnskåd|framkall|mörkrum|brädspel|löp|jogg|cykl|vandr|yoga|skidor|skridsko|bada|badet|isbad|vinterbad|bastu|simm|träning|tränar|gym|skogen|svamp|plocka|veden|vedhugg|hugga ved|kubb|dansa|dansen|dansade|meditation|paddl|fiske|trädgård|gräv|snöskott|utflykt|stretch|qigong|klättr|ridning|hunden|kvällsmeditation)') then ut := ut || 'aktivitet'::text; end if;
  if d->>'typ' = 'reportage' or t ~* (b||'(tillsammans|gemensam|gänget|hela teamet|alla samlade|samlades|gruppen|gruppbild|kollegor|stormöte|gruppretro|vi var|vi satt|vi gick|vi spelade|vi åt|hela gården)') then ut := ut || 'grupp'::text; end if;
  if coalesce(nullif(d->>'land',''),'Sverige') <> 'Sverige' or t ~* (b||'(tåg|flyg|resa|reser |resan|färja|bussen|station|hotell|vandrarhem|semester|på väg till|på väg hem|landat|pendl|bilresa)') then ut := ut || 'resa'::text; end if;
  if d->>'kalla' = 'morgonrutin-privat' or t ~* (b||'(hemma|lägenhet|soffan|hemmet|hemifrån|balkong|kom hem|sambo|barnen|familjen)') then ut := ut || 'hemma'::text; end if;
  -- resten av en teammedlems inlägg räknas som arbete (gäster g: och besökare u: undantas)
  if cardinality(ut) = 0 and au <> '' and au !~ '^(g|u):' and coalesce(d->>'kalla','') <> 'morgonrutin-privat' then ut := ut || 'arbete'::text; end if;
  if coalesce(d->>'bildbestallning','') <> '' or d->'bild'->>'url' is not null or d->'video'->>'url' is not null
     or (jsonb_typeof(d->'videor') = 'array' and jsonb_array_length(d->'videor') > 0) then ut := ut || 'bild'::text; end if;
  return to_jsonb(ut);
end $$;

create or replace function public.docs_post_taggar() returns trigger
language plpgsql set search_path = public as $$
begin
  if new.collection = 'posts' and jsonb_typeof(new.data->'taggar') is distinct from 'array' then
    new.data := new.data || jsonb_build_object('taggar', public.luminus_post_taggar(new.data));
  end if;
  return new;
end $$;

drop trigger if exists docs_post_taggar on public.docs;
create trigger docs_post_taggar before insert or update on public.docs
for each row when (new.collection = 'posts') execute function public.docs_post_taggar();

